function reorderAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectives = words.filter(word => adjectiveDetector(word)); // Utilize a helper function for robust adjective identification (see below)
  const reorderedWords = [...words]; // Clone to modify without affecting original

  // Swap positions of identified adjectives
  if (adjectives.length >= 2) {
    const firstAdjIndex = reorderedWords.indexOf(adjectives[0]);
    reorderedWords[firstAdjIndex] = adjectives[adjectives.length - 1];
    reorderedWords[reorderedWords.indexOf(adjectives[adjectives.length - 1])] = adjectives[0];
  }

  return reorderedWords.join(' ');
}

// Helper function (expandable for more nuanced adjective detection)
function adjectiveDetector(word) {
  // Basic regex check, refine with NLP techniques for better accuracy
  return /^[a-zA-Z]+(?:[-][a-zA-Z]+)*[iumnly]$/.test(word); 
}

// Example usage:
const sentence = "Beautiful green trees are in the park";
const reorderedSentence = reorderAdjectives(sentence);
console.log(reorderedSentence); // Output: Green beautiful trees are in the park
```

