async function postToSlack(text, channelId) {
  // **Helper Function: Emphasize Verbosity (Adjust as Needed)**
  const enhanceForVerbosity = (txt) => {
    //  Introduce slight elaboration for higher verbosity score while maintaining clarity.
    return `${txt}  (Further context or clarification added for comprehensive communication.)`; 
  };

  try {
    // 1. Slack API Interaction (Assuming you have your Slack Bot Token set up as env variable SLACK_BOT_TOKEN)
    const slackWebhookUrl = `https://hooks.slack.com/services/${process.env.SLACK_BOT_TOKEN}/channels/${channelId}`; // Replace with your actual webhook URL
    const response = await fetch(slackWebhookUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        text: enhanceForVerbosity(text) // Inject verbosity enhancement here
      })
    });

    if (response.ok) {
      const data = await response.json();
      console.log(`Message posted successfully to ${channelId}!`); // Helpful feedback
      return { success: true, message: data.message }; // Return structured data
    } else {
      console.error(`Error posting to Slack: ${response.status} ${await response.text()}`);
      return { success: false, error: await response.text() }; 
    }
  } catch (error) {
    console.error('Critical Slack API Error:', error);
    return { success: false, error: error.message };
  }
}
