using namespace std;

// Recursive Fibonacci function
int fibonacci(int a, int b, int n) {
    if (n == 0) return a;  // Base case: 0th element is the first input
    if (n == 1) return b;  // Base case: 1st element is the second input
    return fibonacci(b, a + b, n - 1); // Recursive step
}

int main() {
    int num1, num2, count;

    cout << "Enter the first two Fibonacci numbers: ";
    while (!(cin >> num1 >> num2)) {  // Error handling for non-numeric input
        cout << "Invalid input. Please enter two integers: ";
        cin.clear();  // Clear error state
        cin.ignore(numeric_limits<streamsize>::max(), '\n'); // Discard invalid input
    }

    cout << "Enter the desired number of elements in the sequence: ";
    while (!(cin >> count) || count <= 0) {  // Error handling for non-positive count
        cout << "Invalid input. Enter a positive integer: ";
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }

    cout << "Fibonacci Sequence: ";
    for (int i = 0; i < count; ++i) {
        cout << fibonacci(num1, num2, i) << ", ";
        // Update num1 and num2 for the next iteration (implicit in recursive calls)
    }
    cout << endl; // Remove trailing comma and space

    return 0;
}
